mapper.select:

where action_id = #{actionId}
order by create_time desc
limit 1

select count(*)
from sys_action_center_touch_log
where request_digest = #{requestDigest}
  and create_time >= #{since}

select count(*)
from sys_action_center_touch_log
where channel = #{channel}
  and target_ref = #{targetRef}
  and create_time >= #{since}
  and touch_status in ('SUCCESS', 'DRY_RUN', 'FAILED')


where action_id = #{actionId}
order by create_time desc
limit #{limit}
